214|/* Services */
215|.services{background:var(--white)}
216|.services-grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}
217|.service-group{background:var(--teal-light);border-radius:var(--radius);padding:28px;border:1px solid transparent;transition:var(--transition)}
218|.service-group:hover{border-color:var(--teal);box-shadow:var(--shadow)}
219|.service-group h3{display:flex;align-items:center;gap:8px;font-family:var(--font-body);font-size:1rem;font-weight:600;color:var(--teal-dark);margin-bottom:16px}
