249|/* Footer */
250|.footer{background:var(--dark);color:rgba(255,255,255,0.5);padding:40px 0 24px;font-size:0.82rem}
251|.footer .container{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px}
252|.footer-acc-badge{display:inline-flex;align-items:center;gap:6px;padding:4px 10px;border-radius:4px;border:1px solid rgba(255,255,255,0.1);font-size:0.7rem}
253|
