263|.carousel{position:relative;overflow:hidden;border-radius:var(--radius);margin:0 -8px;max-height:450px}
264|.carousel-track{display:flex;transition:transform 0.5s ease;gap:0;height:100%}
265|.carousel-slide{min-width:33.333%;padding:0 8px;position:relative;box-sizing:border-box;display:flex;align-items:center}
266|.carousel-slide img{width:100%;aspect-ratio:4/5;object-fit:cover;border-radius:var(--radius-sm);max-height:420px}
