<style>
/* ===== CSS LAYERS ===== */
@layer reset, base, tokens, layout, components, utilities, overrides;

@layer reset {
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
  body, h1, h2, h3, p { margin: 0; padding: 0; }
}

@layer base {
  :root {
    --font-primary: var(--font-body);
    --spacing: 1rem;
    --radius: 12px;
  }
  body { font-family: var(--font-primary); line-height: 1.6; }
}

@layer tokens {
  :root {
    /* Brand colors */
    --teal: #2d6a6a;
    --teal-dark: #1d4f4f;
    --teal-light: #e8f2f0;
    --white: #ffffff;
    --dark: #1a1a1a;
    --text: #3d3d3d;
    --text-light: #6b6b6b;
    --border: #e0e0e0;
    --font-display: 'Playfair Display', Georgia, serif;
    --font-body: 'Inter', system-ui, sans-serif;
    --radius: 12px;
    --radius-sm: 8px;
    --shadow: 0 4px 24px rgba(0,0,0,0.06);
    --shadow-md: 0 8px 40px rgba(0,0,0,0.08);
    --transition: 0.4s cubic-bezier(0.25,0.1,0.25,1);

    /* Fluid typography tokens */
    --fs-h1: clamp(2rem, 5vw, 3.2rem);
    --fs-h2: clamp(1.6rem, 3.5vw, 2.4rem);
    --fs-h3: clamp(1.1rem, 2.5vw, 1.3rem);
    --fs-body: clamp(0.95rem, 2vw, 1.05rem);
    --fs-sm: clamp(0.8rem, 1.5vw, 0.9rem);

    /* Spacing tokens */
    --space-xs: clamp(0.25rem, 1vw, 0.5rem);
    --space-sm: clamp(0.5rem, 2vw, 1rem);
    --space-md: clamp(1rem, 3vw, 1.5rem);
    --space-lg: clamp(1.5rem, 4vw, 2.5rem);
    --space-xl: clamp(2rem, 6vw, 4rem);

    /* Glassmorphism tokens */
    --glass-bg: rgba(255,255,255,0.15);
    --glass-border: rgba(255,255,255,0.2);
    --glass-blur: blur(16px);

    /* Light mode tokens (default) */
    --bg: #f8f7f4;
    --surface: #ffffff;
    --text-primary: #1a1a1a;
    --text-secondary: #3d3d3d;
    --text-muted: #6b6b6b;
    --border-color: #e0e0e0;
    --shadow-color: rgba(0,0,0,0.06);
    --shadow-md-color: rgba(0,0,0,0.08);
  }

  /* Dark mode via prefers-color-scheme */
  @media (prefers-color-scheme: dark) {
    :root {
      --bg: #121212;
      --surface: #1e1e1e;
      --text-primary: #e4e4e7;
      --text-secondary: #a1a1aa;
      --text-muted: #71717a;
      --border-color: #27272a;
      --shadow-color: rgba(0,0,0,0.3);
      --shadow-md-color: rgba(0,0,0,0.4);
      --teal: #4fd1c5;
      --teal-dark: #38b2ac;
      --teal-light: #0d2d2d;
      --white: #1e1e1e;
      --dark: #f7fafc;
      --text: #e4e4e7;
      --text-light: #a1a1aa;
      --border: #27272a;
    }
  }
}

@layer layout {
  @supports (container-type: inline-size) {
    .services-grid, .ba-grid, .reviews-grid, .slots-grid, .contact-grid {
      container-type: inline-size;
    }
  }

  @container (min-width: 400px) {
    .service-group { flex-direction: row; align-items: center; }
    .service-item { min-width: 250px; }
  }

  @container (min-width: 600px) {
    .ba-grid { grid-template-columns: 1fr 1fr 1fr; }
    .reviews-grid { grid-template-columns: 1fr 1fr 1fr; }
    .slots-grid { grid-template-columns: 1fr 1fr; }
  }
}

/* ===== TYPOGRAPHY & BASE ===== */
:root {
  --fs-h1: clamp(2rem, 5vw, 3.2rem);
  --fs-h2: clamp(1.6rem, 3.5vw, 2.4rem);
  --fs-h3: clamp(1.1rem, 2.5vw, 1.3rem);
  --fs-body: clamp(0.95rem, 2vw, 1.05rem);
  --fs-sm: clamp(0.8rem, 1.5vw, 0.9rem);
}

h1,h2,h3{font-family:var(--font-display);font-weight:500;line-height:1.2;color:var(--dark)}
h1{font-size:var(--fs-h1)}
