section{padding:var(--space-xl) 0}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; }
body { font-family: var(--font-body); background: var(--bg); color: var(--text-primary); line-height: 1.6; overflow-x: hidden; }
img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
button { cursor: pointer; border: none; background: none; font: inherit; }

/* ===== SKIP LINK & FOCUS ===== */
.skip-link { position: fixed; top: -100px; left: 0; z-index: 9999; padding: 12px 24px; background: var(--teal); color: #fff; font-size: 0.9rem; font-weight: 500; border-radius: 0 0 8px 0; transition: top 0.3s; }
.skip-link:focus { top: 0 }
*:focus-visible { outline: 2px solid var(--teal); outline-offset: 3px; border-radius: 4px; }

/* ===== HEADER ===== */
.header { position: fixed; top: 0; left: 0; right: 0; z-index: 100; padding: 14px 0; transition: var(--transition); background: rgba(var(--bg), 0.9); backdrop-filter: blur(12px); border-bottom: 1px solid var(--border-color); }
.header .container { display: flex; align-items: center; justify-content: space-between; }
.header-logo { font-family: var(--font-display); font-size: 1.4rem; color: var(--teal); font-weight: 500; }
.header-logo span { color: var(--dark); }
.header-nav { display: flex; align-items: center; gap: 28px; }
.header-nav a { font-size: 0.85rem; font-weight: 500; color: var(--text); transition: 0.3s; position: relative; }
.header-nav a::after { content: ''; position: absolute; bottom: -4px; left: 0; width: 0; height: 1.5px; background: var(--teal); transition: 0.3s; }
.header-nav a:hover { color: var(--teal); }
.header-nav a:hover::after { width: 100%; }
.btn { display: inline-flex; align-items: center; gap: 8px; padding: 12px 28px; border-radius: 50px; font-size: 0.88rem; font-weight: 500; transition: var(--transition); white-space: nowrap; }
.btn-primary { background: var(--teal); color: var(--white); }
.btn-primary:hover { background: var(--teal-dark); transform: translateY(-2px); box-shadow: 0 8px 25px rgba(45,106,106,0.3); }
.header .btn-primary { background: var(--teal); color: #fff; box-shadow: 0 4px 15px rgba(45,106,106,0.3); font-weight: 600; }
.header .btn-primary:hover { background: var(--teal-dark); transform: translateY(-2px); box-shadow: 0 8px 25px rgba(45,106,106,0.4); }
.btn-outline { background: transparent; color: var(--teal); border: 1.5px solid var(--teal); }
.btn-outline:hover { background: var(--teal); color: var(--white); }
.mobile-toggle { display: none; flex-direction: column; gap: 5px; cursor: pointer; }
.mobile-toggle span { display: block; width: 24px; height: 2px; background: var(--dark); border-radius: 2px; transition: 0.3s; }

/* ===== HERO ===== */
.hero { min-height: 90dvh; display: grid; grid-template-columns: 1fr 1fr; padding-top: 80px; background: linear-gradient(135deg, #f0f5f3 0%, #f8f7f4 50%, #f0f0ec 100%); position: relative; overflow: hidden; }
.hero-left { display: flex; align-items: center; padding: 0 48px; position: relative; z-index: 2; }
.hero-left .hero-content { max-width: 520px; }
.hero-right { position: relative; overflow: hidden; border-radius: var(--radius) 0 0 var(--radius); display: flex; align-items: stretch; }
.hero-right img { width: 100%; height: 100%; object-fit: cover; }
.hero .eyebrow { font-size: 0.75rem; font-weight: 500; text-transform: uppercase; letter-spacing: 0.12em; color: var(--teal); margin-bottom: 1rem; }
.hero h1 { margin-bottom: 0.4em; }
.hero h1 em { font-style: italic; color: var(--teal); }
.hero p { font-size: 1.05rem; color: var(--text-muted); margin-bottom: 2rem; max-width: 480px; }
.hero-badges { display: flex; gap: 12px; margin-top: 1.5rem; flex-wrap: wrap; }
.hero-badge { display: inline-flex; align-items: center; gap: 6px; padding: 8px 16px; border-radius: 50px; background: var(--glass-bg); backdrop-filter: var(--glass-blur); border: 1px solid var(--glass-border); font-size: 0.8rem; color: var(--text); box-shadow: var(--shadow); }

/* ===== SECTION COMMON ===== */
.section-label { font-size: 0.7rem; font-weight: 600; text-transform: uppercase; letter-spacing: 0.12em; color: var(--teal); margin-bottom: 0.75rem; display: flex; align-items: center; gap: 10px; }
.section-label::before { content: ''; display: inline-block; width: 30px; height: 1.5px; background: var(--teal); }

/* ===== SERVICES ===== */
.services { background: var(--surface); }
.services-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
.service-group { background: var(--glass-bg); backdrop-filter: var(--glass-blur); border: 1px solid var(--glass-border); border-radius: var(--radius); padding: 28px; border: 1px solid transparent; transition: var(--transition); }
.service-group:hover { border-color: var(--teal); box-shadow: var(--shadow-md); }
@media (prefers-color-scheme: dark) {
  .service-group { background: rgba(30,30,30,0.5); backdrop-filter: var(--glass-blur); border: 1px solid rgba(255,255,255,0.1); }
